from pysat.solvers import Glucose3
from pysat.card import *

# Parse edges
edges_str = """(0,1), (0,3), (0,6), (0,7), (0,9), (0,18), (0,21), (0,24), (1,7), (1,8), (1,12), (1,13), (1,24), (1,26), (1,28), (2,3), (2,11), (2,15), (2,20), (2,21), (2,22), (2,24), (2,36), (3,11), (3,12), (3,28), (3,29), (3,36), (4,5), (4,14), (4,20), (4,30), (4,35), (5,17), (5,25), (5,30), (5,33), (5,34), (6,8), (6,20), (6,24), (6,30), (7,11), (7,17), (7,19), (7,21), (7,24), (7,25), (7,27), (7,32), (8,12), (8,13), (8,17), (8,21), (8,22), (8,28), (8,36), (9,12), (9,13), (9,19), (9,21), (9,27), (9,28), (9,29), (9,32), (9,34), (10,21), (10,31), (11,12), (11,13), (11,16), (11,29), (13,14), (13,18), (13,30), (13,35), (13,36), (14,16), (14,31), (15,22), (15,24), (15,25), (15,28), (15,30), (15,33), (16,18), (16,27), (16,28), (16,34), (17,19), (17,23), (17,25), (17,30), (17,32), (17,36), (18,30), (18,35), (18,36), (19,24), (19,34), (19,36), (20,21), (20,24), (20,27), (20,33), (21,26), (21,33), (21,36), (22,28), (22,34), (23,31), (23,36), (24,29), (24,32), (24,35), (25,31), (25,32), (25,35), (26,29), (26,34), (27,29), (27,30), (27,34), (27,35), (27,36), (28,29), (28,32), (28,35), (30,32), (30,36), (32,36), (33,35), (33,36)"""

edges = []
for pair in edges_str.replace(' ', '').split('),'):
    pair = pair.strip('()')
    if pair:
        u, v = map(int, pair.split(','))
        edges.append((u, v))

print(f"Number of edges: {len(edges)}")
print(f"Vertices: 0-36 (37 vertices)")

# Build adjacency list
adj = {i: set() for i in range(37)}
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Use SAT encoding for 4-coloring
# Variable x_{v,c} = True means vertex v has color c
# For each vertex v: exactly one color (at-least-one + at-most-one)
# For each edge (u,v): not both same color

solver = Glucose3()

n = 37
k = 4

# Variable mapping: var(v, c) = v * k + c + 1 (1-indexed for SAT)
def var(v, c):
    return v * k + c + 1

# Each vertex gets at least one color
for v in range(n):
    solver.add_clause([var(v, c) for c in range(k)])

# Each vertex gets at most one color (pairwise exclusion)
for v in range(n):
    for c1 in range(k):
        for c2 in range(c1+1, k):
            solver.add_clause([-var(v, c1), -var(v, c2)])

# Adjacent vertices cannot have the same color
for u, v in edges:
    for c in range(k):
        solver.add_clause([-var(u, c), -var(v, c)])

# Solve
if solver.solve():
    model = solver.get_model()
    coloring = [0] * n
    for v in range(n):
        for c in range(k):
            if model[var(v, c) - 1] > 0:
                coloring[v] = c
                break
    print("SATISFIABLE")
    print(f"Coloring: {coloring}")

    # Verify
    valid = True
    for u, v in edges:
        if coloring[u] == coloring[v]:
            print(f"ERROR: Edge ({u},{v}) has same color {coloring[u]}")
            valid = False
    if valid:
        print("Verification: VALID")
else:
    print("UNSATISFIABLE")

solver.delete()
